from taf.vran.vdu.enb.rest.client import HttpClient
from taf.vran.vdu.enb.rest.utilities.connection_details import ConnectionDetails


class CMLicensedv1(HttpClient):
    def __init__(self, base_url: str, connection_details: ConnectionDetails) -> None:
        super().__init__(connection_details)
        self.base_url = base_url + "/api/licensed/v1"

    def get_managed_objects(self, class_name: str, timeout: int) -> list:
        """
        Gets managed objects with parameters.

        :param str class_name: Class name for object matching filtering.
        :param int timeout: Timeout for the operation. Defaults to 30s.

        :returns: List with managed objects and their parameters, for example:

            .. code-block:: python

                [
                  {
                    "className": "NTP",
                    "distName": "MRBTS-100/MNL-1/MNLENT-1/SYNC-1/CLOCK-1/NTP-1",
                    "version": "TNL5G19_1901_010",
                    "payload": "{\"ntpAlarmingThreshold\": 180, \"ntpServerIpAddrList\":[\"10.192.33.0\",\"10.192.33.1\"]}"
                  }
                ]
        :rtype: list
        """
        return self.send_request(
            method="GET",
            endpoint=f"/current-plan?className={class_name}",
            timeout=timeout
        )
